"""In-model FAISS vector store (``faiss-cpu``).

:class:`FAISS_Store` is the single FAISS implementation used across Rasa:

* **Enterprise Search** — load/chunk documents from disk, implement
  :class:`~rasa.core.information_retrieval.information_retrieval.InformationRetrieval`
* **CALM flow retrieval** — embed flows at train time, semantic filter at runtime
* **IntentlessPolicy** — response / conversation-sample indexes in the model tarball

Remote vector DBs (Milvus, Qdrant) use their own ``*_Store`` classes. In-model
features should depend on the shared search/persist surface of ``FAISS_Store``
(``from_texts``, ``from_documents``, ``save``, ``load_native``,
``asimilarity_search_with_score``, …) so a future backend swap can introduce
a common protocol without rewriting call sites.

Persistence is ``index.faiss`` + ``store.json`` (no pickle). Legacy LangChain
``index.pkl`` artifacts are rejected without being opened.
"""

from __future__ import annotations

import json
import uuid
from pathlib import Path
from typing import TYPE_CHECKING, Any, Dict, List, Text, Tuple

import faiss
import numpy as np
import structlog

from rasa.core.information_retrieval import (
    InformationRetrieval,
    InformationRetrievalException,
    SearchResultList,
)
from rasa.core.information_retrieval.ingestion.faq_parser import _format_faq_documents
from rasa.core.information_retrieval.ingestion.text_splitter import (
    RecursiveCharacterTextSplitter,
)
from rasa.core.information_retrieval.models import Document
from rasa.shared.exceptions import RasaException
from rasa.shared.providers.embedding.embedding_utils import (
    aembed_query,
    embed_documents,
    embed_query,
)
from rasa.utils.endpoints import EndpointConfig

if TYPE_CHECKING:
    from rasa.shared.providers.embedding.embedding_client import EmbeddingClient

logger = structlog.get_logger()

INDEX_FAISS_FILENAME = "index.faiss"
STORE_JSON_FILENAME = "store.json"
LEGACY_PICKLE_FILENAME = "index.pkl"

STORE_JSON_VERSION = 1

DISTANCE_METRIC_INNER_PRODUCT = "inner_product"
DISTANCE_METRIC_L2 = "l2"

# Number of top documents returned by the Enterprise Search FAISS retriever.
DEFAULT_SEARCH_K = 4

# Batch size to avoid hitting embedding API token limits during index build.
EMBEDDING_BATCH_SIZE = 50

# Enterprise Search document chunking defaults.
DEFAULT_CHUNK_SIZE = 1000
DEFAULT_CHUNK_OVERLAP = 20

LEGACY_RETRAIN_ERROR_MESSAGE = (
    "Cannot load this model: it contains a legacy LangChain-serialized FAISS "
    f"index ('{LEGACY_PICKLE_FILENAME}'), which is no longer supported. "
    "Retrain the model with the current version of Rasa Pro before running it "
    "again (for Enterprise Search, also re-ingest your documents)."
)

MISSING_INDEX_ERROR_MESSAGE = (
    "No Enterprise Search FAISS index was found at '{path}'. Expected "
    f"'{STORE_JSON_FILENAME}' (and '{INDEX_FAISS_FILENAME}') under "
    f"'documents_faiss/'. The model may not have been trained with Enterprise "
    "Search enabled, or the index was not persisted. Please retrain the model "
    "(and re-ingest documents) to use semantic search."
)


class LegacyFaissModelError(RasaException):
    """Raised when a legacy LangChain-pickled FAISS model is detected."""

    def __init__(self, message: str = LEGACY_RETRAIN_ERROR_MESSAGE) -> None:
        super().__init__(message)


class MissingFaissIndexError(RasaException):
    """Raised when an Enterprise Search FAISS index is expected but missing."""

    def __init__(self, path: str | Path) -> None:
        super().__init__(MISSING_INDEX_ERROR_MESSAGE.format(path=path))


class FAISS_Store(InformationRetrieval):
    """In-model FAISS vector index.

    Construct an empty index with ``FAISS_Store(embeddings, ...)`` and populate
    via ``add_texts`` / ``from_texts`` / ``from_documents``, or open an
    Enterprise Search index with ``index_path`` (and optional ``create_index``).
    """

    def __init__(
        self,
        embeddings: "EmbeddingClient",
        index_path: str | None = None,
        docs_folder: str | None = None,
        create_index: bool = False,
        parse_as_faq_pairs: bool = False,
        *,
        distance_metric: str = DISTANCE_METRIC_L2,
        normalize_l2: bool = False,
    ) -> None:
        super().__init__(embeddings)
        self.distance_metric = distance_metric
        self.normalize_l2 = normalize_l2
        self.chunk_size = DEFAULT_CHUNK_SIZE
        self.chunk_overlap = DEFAULT_CHUNK_OVERLAP
        self.parse_as_faq_pairs = parse_as_faq_pairs
        self._index: Any | None = None
        self.documents: Dict[str, Document] = {}
        self.index_to_docstore_id: Dict[int, str] = {}

        if index_path is None:
            return

        folder = Path(index_path) / "documents_faiss"

        if create_index:
            logger.info(
                "information_retrieval.faiss_store.create_index",
                path=folder.absolute(),
            )
            self._build_enterprise_index(docs_folder)
            self.save(folder)
        else:
            logger.info(
                "information_retrieval.faiss_store.load_index",
                path=folder.absolute(),
            )
            if (folder / STORE_JSON_FILENAME).exists():
                self._adopt_index_state(FAISS_Store.load_native(folder, embeddings))
            elif (folder / LEGACY_PICKLE_FILENAME).exists():
                logger.error(
                    "information_retrieval.faiss_store.legacy_model_detected",
                    path=str(folder),
                    event_info=LEGACY_RETRAIN_ERROR_MESSAGE,
                )
                raise LegacyFaissModelError()
            else:
                logger.error(
                    "information_retrieval.faiss_store.missing_index",
                    path=str(folder),
                )
                raise MissingFaissIndexError(folder)

    def _adopt_index_state(self, other: "FAISS_Store") -> None:
        self._index = other._index
        self.documents = other.documents
        self.index_to_docstore_id = other.index_to_docstore_id
        self.distance_metric = other.distance_metric
        self.normalize_l2 = other.normalize_l2

    def _new_faiss_index(self, dimension: int):  # type: ignore[no-untyped-def]
        if self.distance_metric == DISTANCE_METRIC_INNER_PRODUCT:
            return faiss.IndexFlatIP(dimension)
        return faiss.IndexFlatL2(dimension)

    def _prepare_vectors(self, embeddings: List[List[float]]) -> "np.ndarray":
        vectors = np.array(embeddings, dtype=np.float32)
        if vectors.ndim == 1:
            vectors = vectors.reshape(1, -1)
        if self.normalize_l2:
            vectors = np.ascontiguousarray(vectors)
            faiss.normalize_L2(vectors)
        return vectors

    @classmethod
    def from_texts(
        cls,
        texts: List[str],
        embeddings: "EmbeddingClient",
        metadatas: List[dict] | None = None,
        *,
        distance_metric: str = DISTANCE_METRIC_L2,
        normalize_l2: bool = False,
    ) -> "FAISS_Store":
        store = cls(
            embeddings,
            distance_metric=distance_metric,
            normalize_l2=normalize_l2,
        )
        store.add_texts(texts, metadatas=metadatas)
        return store

    @classmethod
    def from_documents(
        cls,
        documents: List[Document],
        embeddings: "EmbeddingClient",
        *,
        distance_metric: str = DISTANCE_METRIC_L2,
        normalize_l2: bool = False,
    ) -> "FAISS_Store":
        texts = [doc.text for doc in documents]
        metadatas = [doc.metadata for doc in documents]
        return cls.from_texts(
            texts,
            embeddings,
            metadatas=metadatas,
            distance_metric=distance_metric,
            normalize_l2=normalize_l2,
        )

    def add_texts(
        self, texts: List[str], metadatas: List[dict] | None = None
    ) -> List[str]:
        if not texts:
            return []
        metadatas = metadatas or [{} for _ in texts]
        vectors = embed_documents(self.embeddings, list(texts))
        return self._add_embeddings(list(texts), vectors, metadatas)

    def _add_embeddings(
        self,
        texts: List[str],
        embeddings: List[List[float]],
        metadatas: List[dict],
    ) -> List[str]:
        vectors = self._prepare_vectors(embeddings)
        if self._index is None:
            self._index = self._new_faiss_index(vectors.shape[1])

        starting_row = self._index.ntotal
        self._index.add(vectors)

        ids: List[str] = []
        for offset, (text, metadata) in enumerate(zip(texts, metadatas)):
            doc_id = str(uuid.uuid4())
            self.documents[doc_id] = Document(text=text, metadata=metadata or {})
            self.index_to_docstore_id[starting_row + offset] = doc_id
            ids.append(doc_id)
        return ids

    # ------------------------------------------------------------------ #
    # Search
    # ------------------------------------------------------------------ #
    def _search_by_vector(
        self, embedding: List[float], k: int
    ) -> List[Tuple[Document, float]]:
        if self._index is None or self._index.ntotal == 0:
            return []
        vectors = self._prepare_vectors([embedding])
        scores, indices = self._index.search(vectors, k)
        results: List[Tuple[Document, float]] = []
        for score, row in zip(scores[0], indices[0]):
            if row == -1:
                continue
            doc_id = self.index_to_docstore_id.get(int(row))
            if doc_id is None:
                continue
            results.append((self.documents[doc_id], float(score)))
        return results

    def similarity_search_with_score_by_vector(
        self, embedding: List[float], k: int = DEFAULT_SEARCH_K
    ) -> List[Tuple[Document, float]]:
        return self._search_by_vector(embedding, k)

    def similarity_search_by_vector(
        self, embedding: List[float], k: int = DEFAULT_SEARCH_K
    ) -> List[Document]:
        return [doc for doc, _ in self._search_by_vector(embedding, k)]

    def similarity_search(
        self, query: str, k: int = DEFAULT_SEARCH_K
    ) -> List[Document]:
        embedding = embed_query(self.embeddings, query)
        return [doc for doc, _ in self._search_by_vector(embedding, k)]

    async def asimilarity_search_with_score(
        self, query: str, k: int = DEFAULT_SEARCH_K
    ) -> List[Tuple[Document, float]]:
        embedding = await aembed_query(self.embeddings, query)
        return self._search_by_vector(embedding, k)

    # ------------------------------------------------------------------ #
    # Persistence
    # ------------------------------------------------------------------ #
    def save(self, path: str | Path) -> None:
        folder = Path(path)
        folder.mkdir(parents=True, exist_ok=True)

        if self._index is not None:
            faiss.write_index(self._index, str(folder / INDEX_FAISS_FILENAME))

        payload = {
            "version": STORE_JSON_VERSION,
            "distance_metric": self.distance_metric,
            "normalize_l2": self.normalize_l2,
            "documents": {
                doc_id: {"text": doc.text, "metadata": doc.metadata}
                for doc_id, doc in self.documents.items()
            },
            "index_to_docstore_id": {
                str(row): doc_id for row, doc_id in self.index_to_docstore_id.items()
            },
        }
        (folder / STORE_JSON_FILENAME).write_text(
            json.dumps(payload, ensure_ascii=False), encoding="utf-8"
        )

    @classmethod
    def load_native(
        cls, path: str | Path, embeddings: "EmbeddingClient"
    ) -> "FAISS_Store":
        """Load a FAISS store from a native ``index.faiss`` + ``store.json`` directory.

        Args:
            path: Directory containing the persisted index and store metadata.
            embeddings: Embedding client used for subsequent similarity searches.

        Returns:
            A reconstructed :class:`FAISS_Store` ready for search.

        Raises:
            FileNotFoundError: If ``store.json`` or ``index.faiss`` is missing.
            RasaException: If ``store.json`` has an unsupported version.
        """
        folder = Path(path)
        store_json_path = folder / STORE_JSON_FILENAME
        index_path = folder / INDEX_FAISS_FILENAME

        if not store_json_path.exists():
            raise FileNotFoundError(f"No '{STORE_JSON_FILENAME}' found at '{folder}'.")
        if not index_path.exists():
            raise FileNotFoundError(
                f"Found '{STORE_JSON_FILENAME}' but no '{INDEX_FAISS_FILENAME}' "
                f"at '{folder}'. The FAISS index binary is missing."
            )

        payload = json.loads(store_json_path.read_text(encoding="utf-8"))
        version = payload.get("version")
        if version != STORE_JSON_VERSION:
            raise RasaException(
                f"Unsupported '{STORE_JSON_FILENAME}' version: {version}. This "
                f"build of Rasa supports version {STORE_JSON_VERSION}. Please "
                "retrain the model."
            )

        store = cls(
            embeddings,
            distance_metric=payload.get("distance_metric", DISTANCE_METRIC_L2),
            normalize_l2=payload.get("normalize_l2", False),
        )
        store._index = faiss.read_index(str(index_path))
        store.documents = {
            doc_id: Document(text=doc["text"], metadata=doc.get("metadata", {}))
            for doc_id, doc in payload.get("documents", {}).items()
        }
        store.index_to_docstore_id = {
            int(row): doc_id
            for row, doc_id in payload.get("index_to_docstore_id", {}).items()
        }
        return store

    # ------------------------------------------------------------------ #
    # Enterprise Search — document ingestion + InformationRetrieval API
    # ------------------------------------------------------------------ #
    @staticmethod
    def load_documents(docs_folder: str) -> List[Document]:
        folder = Path(docs_folder)
        logger.info(
            "information_retrieval.faiss_store.load_documents",
            docs_folder=folder.absolute(),
        )
        documents: List[Document] = []
        for file_path in sorted(folder.glob("**/*.txt")):
            if not file_path.is_file():
                continue
            documents.append(
                Document(
                    text=file_path.read_text(encoding="utf-8"),
                    metadata={"source": str(file_path)},
                )
            )
        return documents

    def _build_enterprise_index(self, docs_folder: str | None) -> None:
        if not docs_folder:
            raise ValueError("parameter `docs_folder` needs to be specified")

        documents = self.load_documents(docs_folder)

        if not self.parse_as_faq_pairs:
            splitter = RecursiveCharacterTextSplitter(
                chunk_size=self.chunk_size,
                chunk_overlap=self.chunk_overlap,
                length_function=len,
            )
            parsed_documents = splitter.split_documents(documents)
        else:
            parsed_documents = _format_faq_documents(documents)

        logger.info(
            "information_retrieval.faiss_store._create_document_index",
            len_chunks=len(parsed_documents),
        )

        if not parsed_documents:
            raise ValueError(f"No documents found at '{docs_folder}'.")

        texts = [document.text for document in parsed_documents]
        metadatas = [document.metadata for document in parsed_documents]

        ONE_GB = 1024 * 1024 * 1024
        total_size_bytes = sum(len(text.encode("utf-8")) for text in texts)
        if total_size_bytes > 2 * ONE_GB:
            logger.warning(
                "information_retrieval.faiss_store.large_document_size",
                message="Document size exceeds 2GB. FAISS in-memory vector store "
                "performance may degrade significantly with large datasets. "
                "Consider using a dedicated vector database for better performance.",
                total_size_gb=round(total_size_bytes / ONE_GB, 2),
            )

        total_batches = (len(texts) + EMBEDDING_BATCH_SIZE - 1) // EMBEDDING_BATCH_SIZE
        for batch_index, start in enumerate(
            range(0, len(texts), EMBEDDING_BATCH_SIZE), start=1
        ):
            logger.info(
                "information_retrieval.faiss_store._create_document_index"
                ".embedding_batch",
                batch=batch_index,
                total_batches=total_batches,
            )
            self.add_texts(
                texts[start : start + EMBEDDING_BATCH_SIZE],
                metadatas=metadatas[start : start + EMBEDDING_BATCH_SIZE],
            )

    def connect(self, config: EndpointConfig) -> None:
        """In-model FAISS does not connect to a remote server."""
        pass

    async def search(
        self, query: Text, tracker_state: Dict[str, Any], threshold: float = 0.0
    ) -> SearchResultList:
        logger.debug("information_retrieval.faiss_store.search", query=query)
        if self._index is None:
            raise InformationRetrievalException()
        try:
            # NOTE: `threshold` is intentionally ignored for in-model FAISS (R6).
            results = await self.asimilarity_search_with_score(
                query, k=DEFAULT_SEARCH_K
            )
            documents = [doc for doc, _ in results]
        except Exception as exc:
            raise InformationRetrievalException from exc

        return SearchResultList.from_document_list(documents)
